<?php declare(strict_types=1); namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\Department; use App\Models\User; use App\Services\Admin\SiteChecklistItemService; use Illuminate\Http\JsonResponse; final class OptionsController extends Controller { public function __construct(private SiteChecklistItemService $checklist){} public function checklistItems(): JsonResponse { return response()->json(['data'=>$this->checklist->activeOptions()->map(fn($i)=>['id'=>$i->id,'code'=>$i->code,'label'=>$i->localizedLabel()])]); } public function departments(): JsonResponse { return response()->json(['data'=>Department::where('active',true)->orderBy('code')->get(['id','code','name_en'])->map(fn($d)=>['id'=>$d->id,'code'=>$d->code,'name'=>$d->name_en])]); } public function users(): JsonResponse { return response()->json(['data'=>User::where('active',true)->orderBy('name')->get(['id','name','email'])]); }}